:root {
  --color-bg: #f5f5f7;
  --color-card: #ffffff;
  --color-text: #1a1a2e;
  --color-muted: #6b7280;
  --color-border: #e5e7eb;
  --color-border-focus: #6366f1;
  --color-primary: #6366f1;
  --color-primary-hover: #4f46e5;
  --color-error: #ef4444;
  --color-error-bg: #fef2f2;
  --color-helper: #6b7280;
  --radius-field: 10px;
  --radius-card: 20px;
  --shadow-card: 0 4px 6px -1px rgb(0 0 0 / .07), 0 2px 4px -2px rgb(0 0 0 / .05);
  --transition: 150ms ease;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background-color: var(--color-bg);
  color: var(--color-text);
  min-height: 100dvh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 2rem 1rem;
  line-height: 1.5;
}

/* ── Card ── */
.card {
  background: var(--color-card);
  border-radius: var(--radius-card);
  box-shadow: var(--shadow-card);
  width: 100%;
  max-width: 480px;
  padding: 2.5rem 2rem;
}

/* ── Header ── */
.card-header {
  margin-bottom: 2rem;
}

.logo-mark {
  display: inline-flex;
  margin-bottom: 1.25rem;
}

.card-title {
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--color-text);
}

.card-subtitle {
  margin-top: 0.375rem;
  font-size: 0.9375rem;
  color: var(--color-muted);
}

/* ── Form fields ── */
.form-field {
  display: flex;
  flex-direction: column;
  gap: 0.375rem;
  margin-bottom: 1.25rem;
}

.field-label {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--color-text);
  display: flex;
  align-items: center;
  gap: 0.3rem;
}

.required-mark {
  color: var(--color-primary);
}

.optional-mark {
  font-size: 0.8125rem;
  font-weight: 400;
  color: var(--color-muted);
}

.field-input {
  width: 100%;
  height: 2.75rem;
  padding: 0 0.875rem;
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-field);
  font-size: 0.9375rem;
  font-family: inherit;
  color: var(--color-text);
  background: var(--color-card);
  outline: none;
  transition: border-color var(--transition), box-shadow var(--transition), background var(--transition);
}

.field-input::placeholder {
  color: #b0b7c3;
}

.field-input:focus {
  border-color: var(--color-border-focus);
  box-shadow: 0 0 0 3px rgb(99 102 241 / .15);
}

/* Error state */
.form-field.has-error .field-input {
  border-color: var(--color-error);
  background: var(--color-error-bg);
}

.form-field.has-error .field-input:focus {
  box-shadow: 0 0 0 3px rgb(239 68 68 / .15);
}

.field-helper {
  font-size: 0.8125rem;
  color: var(--color-helper);
}

.field-error {
  font-size: 0.8125rem;
  color: var(--color-error);
  min-height: 1em;
  display: none;
}

.form-field.has-error .field-error {
  display: block;
}

/* ── Submit button ── */
.submit-btn {
  margin-top: 0.75rem;
  width: 100%;
  height: 2.875rem;
  background: var(--color-primary);
  color: #fff;
  font-size: 0.9375rem;
  font-weight: 600;
  font-family: inherit;
  border: none;
  border-radius: var(--radius-field);
  cursor: pointer;
  transition: background var(--transition), transform var(--transition), box-shadow var(--transition);
  letter-spacing: 0.01em;
}

.submit-btn:hover {
  background: var(--color-primary-hover);
  box-shadow: 0 4px 12px rgb(99 102 241 / .35);
}

.submit-btn:active {
  transform: translateY(1px);
  box-shadow: none;
}

.submit-btn:focus-visible {
  outline: 3px solid rgb(99 102 241 / .45);
  outline-offset: 2px;
}

/* ── Success state ── */
.success-message {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  padding: 2rem 0 1rem;
  gap: 0.5rem;
}

.success-title {
  font-size: 1.125rem;
  font-weight: 700;
  color: var(--color-text);
  margin-top: 0.5rem;
}

.success-body {
  font-size: 0.9375rem;
  color: var(--color-muted);
}

/* ── Responsive ── */
@media (max-width: 520px) {
  .card {
    padding: 2rem 1.25rem;
    border-radius: 16px;
  }
}
