+function validateForm() {
+  let valid = true;
+
+  const nameInput = getField('full-name');
+  const nameField = document.getElementById('field-name');
+  if (!nameInput.value.trim()) {
+    setError(nameField, nameInput, 'Full name is required.');
+    valid = false;
+  } else {
+    clearError(nameField, nameInput);
+  }
+
+  const emailInput = getField('email-address');
+  const emailField = document.getElementById('field-email');
+  if (!emailInput.value.trim()) {
+    setError(emailField, emailInput, 'Email address is required.');
+    valid = false;
+  } else if (!EMAIL_RE.test(emailInput.value.trim())) {
+    setError(emailField, emailInput, 'Please enter a valid email address.');
+    valid = false;
+  } else {
+    clearError(emailField, emailInput);
+  }
+
+  const phoneInput = getField('phone-number');
+  const phoneField = document.getElementById('field-phone');
+  if (phoneInput.value.trim() && !PHONE_RE.test(phoneInput.value.trim())) {
+    setError(phoneField, phoneInput, 'Please enter a valid phone number.');
+    valid = false;
+  } else {
+    clearError(phoneField, phoneInput);
+  }
+
+  return valid;
+}
+
+// Clear individual field errors on input after first submission attempt
+let submitted = false;
+
+['full-name', 'email-address', 'phone-number'].forEach(id => {
+  const input = getField(id);
+  input.addEventListener('input', () => {
+    if (!submitted) return;
+    const field = input.closest('.form-field');
+    clearError(field, input);
+  });
+});
+
+form.addEventListener('submit', e => {
+  e.preventDefault();
+  submitted = true;
+
+  if (!validateForm()) {
+    const firstError = form.querySelector('.form-field.has-error .field-input');
+    if (firstError) firstError.focus();
+    return;
+  }
+
+  form.hidden = true;
+  successMessage.hidden = false;
+});
